"128 :     protected final double doSolve() {
129 :         // Get initial solution
130 :         double x0 = getMin();
131 :         double x1 = getMax();
132 :         double f0 = computeObjectiveValue(x0);
133 :         double f1 = computeObjectiveValue(x1);
134 : 
135 :         // If one of the bounds is the exact root, return it. Since these are
136 :         // not under-approximations or over-approximations, we can return them
137 :         // regardless of the allowed solutions.
138 :         if (f0 == 0.0) {
139 :             return x0;
140 :         }
141 :         if (f1 == 0.0) {
142 :             return x1;
143 :         }
144 : 
145 :         // Verify bracketing of initial solution.
146 :         verifyBracketing(x0, x1);
147 : 
148 :         // Get accuracies.
149 :         final double ftol = getFunctionValueAccuracy();
150 :         final double atol = getAbsoluteAccuracy();
151 :         final double rtol = getRelativeAccuracy();
152 : 
153 :         // Keep track of inverted intervals, meaning that the left bound is
154 :         // larger than the right bound.
155 :         boolean inverted = false;
156 : 
157 :         // Keep finding better approximations.
158 :         while (true) {
159 :             // Calculate the next approximation.
160 :             final double x = x1 - ((f1 * (x1 - x0)) / (f1 - f0));
161 :             final double fx = computeObjectiveValue(x);
162 : 
163 :             // If the new approximation is the exact root, return it. Since
164 :             // this is not an under-approximation or an over-approximation,
165 :             // we can return it regardless of the allowed solutions.
166 :             if (fx == 0.0) {
167 :                 return x;
168 :             }
169 : 
170 :             // Update the bounds with the new approximation.
171 :             if (f1 * fx < 0) {
172 :                 // The value of x1 has switched to the other bound, thus inverting
173 :                 // the interval.
174 :                 x0 = x1;
175 :                 f0 = f1;
176 :                 inverted = !inverted;
177 :             } else {
178 :                 switch (method) {
179 :                 case ILLINOIS:
180 :                     f0 *= 0.5;
181 :                     break;
182 :                 case PEGASUS:
183 :                     f0 *= f1 / (f1 + fx);
184 :                     break;
185 :                 case REGULA_FALSI:
186 :                     // Nothing.
187 :                     if (x == x1) {
188 :                         x0 = 0.5 * (x0 + x1 - FastMath.max(rtol * FastMath.abs(x1), atol));
189 :                         f0 = computeObjectiveValue(x0);
190 :                     }
191 :                     break;
192 :                 default:
193 :                     // Should never happen.
194 :                     throw new MathInternalError();
195 :                 }
196 :             }
197 :             // Update from [x0, x1] to [x0, x].
198 :             x1 = x;
199 :             f1 = fx;
200 : 
201 :             // If the function value of the last approximation is too small,
202 :             // given the function value accuracy, then we can't get closer to
203 :             // the root than we already are.
204 :             if (FastMath.abs(f1) <= ftol) {
205 :                 switch (allowed) {
206 :                 case ANY_SIDE:
207 :                     return x1;
208 :                 case LEFT_SIDE:
209 :                     if (inverted) {
210 :                         return x1;
211 :                     }
212 :                     break;
213 :                 case RIGHT_SIDE:
214 :                     if (!inverted) {
215 :                         return x1;
216 :                     }
217 :                     break;
218 :                 case BELOW_SIDE:
219 :                     if (f1 <= 0) {
220 :                         return x1;
221 :                     }
222 :                     break;
223 :                 case ABOVE_SIDE:
224 :                     if (f1 >= 0) {
225 :                         return x1;
226 :                     }
227 :                     break;
228 :                 default:
229 :                     throw new MathInternalError();
230 :                 }
231 :             }
232 : 
233 :             // If the current interval is within the given accuracies, we
234 :             // are satisfied with the current approximation.
235 :             if (FastMath.abs(x1 - x0) < FastMath.max(rtol * FastMath.abs(x1),
236 :                                                      atol)) {
237 :                 switch (allowed) {
238 :                 case ANY_SIDE:
239 :                     return x1;
240 :                 case LEFT_SIDE:
241 :                     return inverted ? x1 : x0;
242 :                 case RIGHT_SIDE:
243 :                     return inverted ? x0 : x1;
244 :                 case BELOW_SIDE:
245 :                     return (f1 <= 0) ? x1 : x0;
246 :                 case ABOVE_SIDE:
247 :                     return (f1 >= 0) ? x1 : x0;
248 :                 default:
249 :                     throw new MathInternalError();
250 :                 }
251 :             }
252 :         }
253 :     }"

